/* SPECULATIVE STARTER - GHOST COP 'PROBLEMS' DRUMS */

// A driving, gritty techno drum kit.
// The core is a distorted kick, a noise snare, and metallic hats.

// Effects Chain: Add a master channel compressor and some light saturation.
// const masterComp = new Tone.Compressor(-20, 6).toDestination();
// const masterLimiter = new Tone.Limiter(-3).connect(masterComp);

// Industrial Kick: MembraneSynth gives the body, drive adds the grit.
const kick = new Tone.MembraneSynth({
	"pitchDecay": 0.01,
	"octaves": 8,
	"oscillator": {"type": "fmsine"},
	"envelope": {"attack": 0.001, "decay": 0.3, "sustain": 0.01, "release": 0.2},
}).connect(new Tone.Distortion(0.5).connect(masterLimiter));
const kickPattern = new Tone.Sequence((time, note) => {
	kick.triggerAttackRelease(note, '8n', time);
}, ['A1', 'A1', 'A1', 'A1'], '4n').start(0);

// Noise Snare: Gated white noise with a bandpass filter for a cracking sound.
const snare = new Tone.NoiseSynth({
	"noise": {"type": "white"},
	"envelope": {"attack": 0.005, "decay": 0.1, "sustain": 0},
	"filter": {"type": 'bandpass', "Q": 1.5, "frequency": 2500}
}).connect(masterLimiter);
const snarePattern = new Tone.Sequence((time) => {
	snare.triggerAttack(time);
}, [null, 'x', null, 'x'], '4n').start(0);

// Closed Hi-Hat: MetalSynth with a tight envelope.
const hihat = new Tone.MetalSynth({
	"frequency": 250,
	"harmonicity": 7.1,
	"modulationIndex": 22,
	"envelope": {"decay": 0.1, "release": 0.05},
	"volume": -15
}).connect(masterLimiter);
const hatPattern = new Tone.Sequence((time) => {
	hihat.triggerAttack(time);
}, [null, 'x', null, 'x', null, 'x', null, 'x'], '8n').start(0);

// Set tempo and start.
// Tone.Transport.bpm.value = 126;
// Tone.Transport.start();

/* SPECULATIVE STARTER - This is a rough sketch. */

// Set up global effects
const reverb = new Tone.Reverb(5).toDestination();
const chorus = new Tone.Chorus(4, 2.5, 0.5).toDestination();

// Grit Bass (MonoSynth on 8ths)
// Notes: ['E2', 'E2', 'E2', 'E2', 'C2', 'C2', 'C2', 'C2']
const bassSynth = new Tone.MonoSynth({
  oscillator: { type: 'sawtooth' },
  envelope: { attack: 0.02, decay: 0.2, release: 0.3 },
  filterEnvelope: { attack: 0.01, decay: 0.1, sustain: 0.5, release: 0.5, baseFrequency: 200, octaves: 2.5 },
}).toDestination();

// Epic Saw Lead (PolySynth)
// Use a fat, detuned oscillator and connect to chorus/reverb
const leadSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 0.2, release: 1.5 },
  volume: -8
}).connect(chorus).connect(reverb);

// Trance Arp (Sequenced Synth on 16ths)
// Notes: ['E4', 'G4', 'B4', 'G4']
const arpSynth = new Tone.Synth({
  oscillator: { type: 'sawtooth' },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.1, release: 0.1 },
  volume: -18
}).connect(reverb);

// Cathedral Pad (PolySynth with long ADSR)
const padSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsquare', count: 7, spread: 40 },
  envelope: { attack: 1.8, release: 4.0 },
  volume: -22
}).connect(chorus).connect(reverb);

// Set tempo and start
Tone.Transport.bpm.value = 126;
Tone.Transport.start();
